using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddSingleton<Notebook>();

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchService>();

var host = builder.Build();

var researchService = host.Services.GetRequiredService<ResearchService>();

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");
await researchService.ResearchAsync(topic, CancellationToken.None);

// --- Services ---

/// <summary>Orchestrates a research agent that searches the web and takes notes.</summary>
sealed class ResearchService(IChatClient chatClient, Notebook notebook)
{
    public async Task ResearchAsync(string topic, CancellationToken ct)
    {
        var tools = new AIToolCollection
        {
            AIFunctionFactory.Create(
                (string query) => SearchWebAsync(query),
                "search_web",
                "Searches the web for the given query and returns a list of result snippets."),
            AIFunctionFactory.Create(
                ([Description("The key insight or fact to save")] string note) =>
                {
                    notebook.Add(note);
                    return $"Note saved. You now have {notebook.Notes.Count} note(s).";
                },
                "save_note",
                "Saves a research note for later use in the summary."),
            AIFunctionFactory.Create(
                () => notebook.Notes.Count == 0
                    ? "No notes saved yet."
                    : string.Join("\n", notebook.Notes.Select((n, i) => $"{i + 1}. {n}")),
                "read_notes",
                "Reads all saved research notes.")
        };

        var agent = new ChatClientAgent(chatClient, "ResearchAgent")
        {
            Instructions = """
                You are a research agent. Your goal is to research the given topic thoroughly.

                Follow this process:
                1. Search the web for the topic using 2-3 different search queries to get broad coverage.
                2. For each search, save the most important findings as notes using the save_note tool.
                3. After gathering enough information, read your notes and produce a well-structured summary.

                Your final message should be the summary, formatted with:
                - A title
                - Key findings (bulleted)
                - A brief conclusion
                """,
        };

        var options = new AgentInvokeOptions
        {
            MaximumIterations = 10,
            ModelOptions = new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 2048,
                Tools = [.. tools],
            },
        };

        var history = new List<ChatMessage>
        {
            new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
        };

        await foreach (var message in agent.InvokeStreamingAsync(history, options, ct))
        {
            if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
            {
                Console.Write(message.Text);
            }
        }

        Console.WriteLine();
        Console.WriteLine($"\n--- {notebook.Notes.Count} note(s) saved during research ---");
    }

    private static Task<string> SearchWebAsync(string query)
    {
        // Simulated web search — replace with a real search API (Bing, Google, Tavily, etc.)
        var results = new Dictionary<string, string[]>(StringComparer.OrdinalIgnoreCase)
        {
            ["artificial intelligence"] =
            [
                "AI is intelligence demonstrated by machines, as opposed to natural intelligence displayed by animals and humans.",
                "Modern AI techniques include deep learning, reinforcement learning, and large language models.",
                "Key applications: healthcare diagnostics, autonomous vehicles, natural language processing, and robotics.",
                "The global AI market is projected to reach $1.8 trillion by 2030.",
                "Ethical concerns include bias in algorithms, job displacement, and privacy issues.",
            ],
            ["climate change"] =
            [
                "Global average temperature has risen ~1.1°C since pre-industrial times.",
                "The Paris Agreement aims to limit warming to 1.5°C above pre-industrial levels.",
                "Key contributors: fossil fuel combustion, deforestation, and industrial processes.",
                "Effects include rising sea levels, extreme weather events, and biodiversity loss.",
                "Renewable energy adoption has accelerated — solar costs dropped 89% in the last decade.",
            ],
            ["quantum computing"] =
            [
                "Quantum computers use qubits that can exist in superposition of 0 and 1 simultaneously.",
                "Major players: IBM, Google, Microsoft, and IonQ are racing toward quantum advantage.",
                "Applications: cryptography, drug discovery, materials science, and optimization problems.",
                "Google claimed quantum supremacy in 2019 with its 53-qubit Sycamore processor.",
                "Current challenges: error correction, decoherence, and scaling qubit counts.",
            ],
        };

        // Find best matching results or return a generic response
        var match = results.Keys.FirstOrDefault(k => query.Contains(k, StringComparison.OrdinalIgnoreCase));
        if (match is null)
        {
            // Try partial keyword matching
            match = results.Keys.FirstOrDefault(k =>
                k.Split(' ').Any(word => query.Contains(word, StringComparison.OrdinalIgnoreCase)));
        }

        var snippets = match is not null
            ? results[match]
            : [$"Search results for '{query}': This is a simulated search. Replace SearchWebAsync with a real search API (Bing Search, Google Custom Search, or Tavily) for production use."];

        var formatted = string.Join("\n", snippets.Select((s, i) => $"[{i + 1}] {s}"));
        return Task.FromResult($"Search results for '{query}':\n{formatted}");
    }
}

/// <summary>Thread-safe notebook for storing research notes.</summary>
sealed class Notebook
{
    private readonly List<string> _notes = [];
    private readonly Lock _lock = new();

    public IReadOnlyList<string> Notes
    {
        get { lock (_lock) return [.. _notes]; }
    }

    public void Add(string note)
    {
        lock (_lock) _notes.Add(note);
    }
}

